export function tr(lang:Lang,key:string){return rows[key]?.[Object.keys(languages).indexOf(lang)]||rows[key]?.[0]||key}
export const LocaleContext=createContext<{lang:Lang,t:(key:string)=>string}>({lang:'en',t:k=>tr('en',k)});
export const useLocale=()=>useContext(LocaleContext);
export function eventLabel(e:any,t:(k:string)=>string){if(e.type==='card')return t(e.secondYellow?'secondYellow':e.card);if(e.type==='penaltykick')return `${t('penalties')} · ${t(e.scored?'scored':'missed')}`;return t(e.type==='save'?'saveEvent':e.type)}
export function minute(time:number){return time>=240?'PEN':`${Math.min(120,Math.floor(time/2))}′`}

export function countryLabel(value:string,t:(key:string)=>string){const map:Record<string,string>={England:"countryEngland",Spain:"countrySpain","Club football":"countryClubs","National teams":"countryNations","Your world":"countryWorld"};return map[value]?t(map[value]):value}
